def HolderMean (E : PathSpace S) (beta : ℝ) (P : Measure (StructSpace S)) : Prop :=
  ∀ x, ∀ a ∈ Icc (0 : ℝ) 1, ∀ b ∈ Icc (0 : ℝ) 1,
    |condPotMean E P x a - condPotMean E P x b| ≤ |a-b| ^ beta -- @realizes mux(Holder-beta seminorm at most one)

