def RankTreatmentIndependence (P : Measure (StructSpace S)) : Prop :=
  ∀ x (B D : Set ℝ), MeasurableSet B → MeasurableSet D →
    P.real {w | sU w ∈ B ∧ sA w ∈ D ∧ sX w = x} * strataProb P x =
    P.real {w | sU w ∈ B ∧ sX w = x} * P.real {w | sA w ∈ D ∧ sX w = x}

