def StructuralThreshold (E : PathSpace S) (P : Measure (StructSpace S)) : Prop :=
  ∀ᵐ w ∂P, ∀ a ∈ Icc (0 : ℝ) 1,
    potentialOutcome E w a = if sU w ≤ condPotMean E P (sX w) a then 1 else 0

